-- ==========================================================
-- Auto-generated Import Script for Customers & Procedures with Visit Counts
-- ==========================================================

DO $$
DECLARE
  v_daskent_id UUID;
  v_semerqend_id UUID;
  v_candela_daskent_id UUID;
  v_candela_semerqend_id UUID;
BEGIN
  -- 1. Ensure Branches & Devices
  SELECT branch_id INTO v_daskent_id FROM branch_translations WHERE name ILIKE '%Daşkənd%' OR name ILIKE '%Daskent%' OR name ILIKE '%Doctor laser%' LIMIT 1;
  IF v_daskent_id IS NULL THEN
    v_daskent_id := gen_random_uuid();
  END IF;

  SELECT branch_id INTO v_semerqend_id FROM branch_translations WHERE name ILIKE '%Səmərqənd%' OR name ILIKE '%Semerqend%' OR name ILIKE '%Laser N1%' LIMIT 1;
  IF v_semerqend_id IS NULL THEN
    v_semerqend_id := gen_random_uuid();
  END IF;

  SELECT d.id INTO v_candela_daskent_id FROM devices d JOIN device_translations dt ON dt.device_id = d.id WHERE d.branch_id = v_daskent_id AND dt.type ILIKE '%Candela%' LIMIT 1;
  IF v_candela_daskent_id IS NULL THEN
    SELECT id INTO v_candela_daskent_id FROM devices WHERE branch_id = v_daskent_id LIMIT 1;
    IF v_candela_daskent_id IS NULL THEN
      v_candela_daskent_id := gen_random_uuid();
    END IF;
  END IF;

  SELECT d.id INTO v_candela_semerqend_id FROM devices d JOIN device_translations dt ON dt.device_id = d.id WHERE d.branch_id = v_semerqend_id AND dt.type ILIKE '%Candela%' LIMIT 1;
  IF v_candela_semerqend_id IS NULL THEN
    SELECT id INTO v_candela_semerqend_id FROM devices WHERE branch_id = v_semerqend_id LIMIT 1;
    IF v_candela_semerqend_id IS NULL THEN
      v_candela_semerqend_id := gen_random_uuid();
    END IF;
  END IF;

  -- 2. Create Temp Table for Customers
  CREATE TEMP TABLE temp_import_customers (
    branch_type TEXT,
    first_name TEXT,
    last_name TEXT,
    phone TEXT,
    registered_at TIMESTAMPTZ
  ) ON COMMIT DROP;















  -- Insert Daşkənd customers avoiding duplicates
  SELECT gen_random_uuid(), t.first_name, t.last_name, t.phone, v_daskent_id, t.registered_at
  FROM temp_import_customers t
  WHERE t.branch_type = 'DASKENT'
    AND NOT EXISTS (
      SELECT 1 FROM customers c
      WHERE c.branch_id = v_daskent_id
        AND (
          (t.phone IS NOT NULL AND c.phone = t.phone)
          OR (t.phone IS NULL AND c.first_name = t.first_name AND c.last_name = t.last_name)
        )
    );

  -- Insert Səmərqənd customers avoiding duplicates
  SELECT gen_random_uuid(), t.first_name, t.last_name, t.phone, v_semerqend_id, t.registered_at
  FROM temp_import_customers t
  WHERE t.branch_type = 'SEMERQEND'
    AND NOT EXISTS (
      SELECT 1 FROM customers c
      WHERE c.branch_id = v_semerqend_id
        AND (
          (t.phone IS NOT NULL AND c.phone = t.phone)
          OR (t.phone IS NULL AND c.first_name = t.first_name AND c.last_name = t.last_name)
        )
    );

  -- 3. Create Temp Table for Procedures / Visits
  CREATE TEMP TABLE temp_import_procedures (
    branch_type TEXT,
    first_name TEXT,
    last_name TEXT,
    phone TEXT,
    proc_date TIMESTAMPTZ,
    price NUMERIC(10,2)
  ) ON COMMIT DROP;










































  -- 4. Insert Procedures and calculate visit numbers chronologically per customer
  WITH matched_procedures AS (
    SELECT
      c.id AS customer_id,
      CASE WHEN t.branch_type = 'DASKENT' THEN v_candela_daskent_id ELSE v_candela_semerqend_id END AS device_id,
      t.proc_date AS date,
      t.price AS price,
      ROW_NUMBER() OVER (PARTITION BY c.id ORDER BY t.proc_date ASC) AS visit_number
    FROM temp_import_procedures t
    JOIN customers c ON c.branch_id = (CASE WHEN t.branch_type = 'DASKENT' THEN v_daskent_id ELSE v_semerqend_id END)
      AND (
        (t.phone IS NOT NULL AND c.phone = t.phone)
        OR (t.phone IS NULL AND c.first_name = t.first_name AND c.last_name = t.last_name)
      )
  )
  SELECT
    gen_random_uuid(),
    m.customer_id,
    m.device_id,
    m.date,
    m.visit_number,
    0,
    0,
    m.price,
    0,
    0,
    m.date
  FROM matched_procedures m;

END $$;
